#[tokio::test]
async fn core_retry_429_retry_after() {
    let server = MockServer::start().await;
    Mock::given(path("/x"))
        .respond_with(ResponseTemplate::new(429).insert_header("retry-after", "1"))
        .up_to_n_times(1)
        .mount(&server)
        .await;
    Mock::given(path("/x"))
        .respond_with(ResponseTemplate::new(200).set_body_json(json!({"ok": true})))
        .mount(&server)
        .await;
    let t = transport(&server, |b| b);
    let started = Instant::now();
    let resp = t.get("/x").send().await.expect("retried");
    assert!(started.elapsed() >= Duration::from_secs(1));
    assert_eq!(resp.status(), 200);
    assert_eq!(resp.json::<serde_json::Value>().unwrap()["ok"], true);
    assert_eq!(hits(&server).await, 2);
}

#[tokio::test]
async fn core_retry_503_backoff() {
    let server = MockServer::start().await;
    Mock::given(path("/x"))
        .respond_with(ResponseTemplate::new(503))
        .up_to_n_times(2)
        .mount(&server)
        .await;
    Mock::given(path("/x"))
        .respond_with(ResponseTemplate::new(200))
        .mount(&server)
        .await;
    let rec = Recorder::new();
    let retry = RetryPolicy {
        initial_backoff: Duration::from_millis(40),
        max_backoff: Duration::from_secs(1),
        ..RetryPolicy::default()
    }
    .with_random(RandomSource::fixed(0.5));
    let t = transport(&server, |b| b.retry(retry).hooks(rec.clone()));
    let started = Instant::now();
    t.get("/x").send().await.expect("third attempt succeeds");
    assert_eq!(hits(&server).await, 3);
    let delays: Vec<Duration> = rec.errors().iter().filter_map(|e| e.retry_delay).collect();
    // full jitter: random(0, min(max, initial * 2^n)) with random = 0.5
    assert_eq!(
        delays,
        vec![Duration::from_millis(20), Duration::from_millis(40)]
    );
    assert!(started.elapsed() >= Duration::from_millis(60));
    let attempts: Vec<u32> = rec.requests().iter().map(|r| r.attempt).collect();
    assert_eq!(attempts, vec![1, 2, 3]);
}

