#[tokio::test]
async fn core_retry_post_not_replayed() {
    let server = MockServer::start().await;
    Mock::given(method("POST"))
        .and(path("/five"))
        .respond_with(ResponseTemplate::new(500))
        .mount(&server)
        .await;
    Mock::given(method("POST"))
        .and(path("/four"))
        .respond_with(ResponseTemplate::new(429))
        .up_to_n_times(1)
        .mount(&server)
        .await;
    Mock::given(method("POST"))
        .and(path("/four"))
        .respond_with(ResponseTemplate::new(201))
        .mount(&server)
        .await;
    let t = transport(&server, |b| b);
    let err = t
        .post("/five")
        .json(&json!({"a": 1}))
        .send()
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Unavailable);
    assert_eq!(hits(&server).await, 1);
    let resp = t
        .post("/four")
        .body("x", "text/plain")
        .send()
        .await
        .unwrap();
    assert_eq!(resp.status(), 201);
    assert_eq!(hits(&server).await, 3);
    // explicitly idempotent POST is retried on 500
    let err = t.post("/five").idempotent(true).send().await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Unavailable);
    assert_eq!(hits(&server).await, 7);
    // GET is idempotent and retried on 500
    Mock::given(method("GET"))
        .and(path("/g500"))
        .respond_with(ResponseTemplate::new(500))
        .mount(&server)
        .await;
    t.get("/g500").send().await.unwrap_err();
    assert_eq!(hits(&server).await, 11);
}

