#[tokio::test]
async fn core_cancel() {
    let server = MockServer::start().await;
    Mock::given(path("/slow"))
        .respond_with(ResponseTemplate::new(200).set_delay(Duration::from_secs(5)))
        .mount(&server)
        .await;
    Mock::given(path("/busy"))
        .respond_with(ResponseTemplate::new(503))
        .mount(&server)
        .await;
    let rec = Recorder::new();
    let t = Arc::new(transport(&server, |b| b.hooks(rec.clone())));

    // during the request
    let token = CancellationToken::new();
    let cancel = token.clone();
    tokio::spawn(async move {
        tokio::time::sleep(Duration::from_millis(100)).await;
        cancel.cancel();
    });
    let started = Instant::now();
    let err = t.get("/slow").cancel_token(token).send().await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Cancelled);
    assert!(!err.is_retryable());
    assert!(started.elapsed() < Duration::from_secs(2));
    assert_eq!(
        rec.errors().last().unwrap().error.code(),
        ErrorCode::Cancelled
    );

    // during the backoff sleep
    let retry = RetryPolicy {
        initial_backoff: Duration::from_secs(5),
        max_backoff: Duration::from_secs(5),
        ..RetryPolicy::default()
    }
    .with_random(RandomSource::fixed(1.0));
    let t2 = transport(&server, |b| b.retry(retry));
    let token = CancellationToken::new();
    let cancel = token.clone();
    tokio::spawn(async move {
        tokio::time::sleep(Duration::from_millis(200)).await;
        cancel.cancel();
    });
    let started = Instant::now();
    let err = t2
        .get("/busy")
        .cancel_token(token)
        .send()
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Cancelled);
    assert!(err.message().contains("backoff"), "{err}");
    assert!(started.elapsed() < Duration::from_secs(2));

    // closing the transport cancels in-flight requests and rejects new ones
    let t3 = Arc::new(transport(&server, |b| b));
    let closer = Arc::clone(&t3);
    tokio::spawn(async move {
        tokio::time::sleep(Duration::from_millis(100)).await;
        closer.close();
        closer.close();
    });
    let err = t3.get("/slow").send().await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Cancelled);
    let err = t3.get("/slow").send().await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Cancelled);
    assert!(err.message().contains("client is closed"));
    assert!(t3.is_closed());

    // dropping the future abandons the request
    let dropped = tokio::time::timeout(Duration::from_millis(100), t.get("/slow").send()).await;
    assert!(dropped.is_err());
}

#[tokio::test]
async fn core_errors_mapping() {
    let server = MockServer::start().await;
    let cases = [
        (400, ErrorCode::Validation, false),
        (401, ErrorCode::Authentication, false),
        (403, ErrorCode::PermissionDenied, false),
        (404, ErrorCode::NotFound, false),
        (409, ErrorCode::Conflict, false),
        (412, ErrorCode::Conflict, false),
        (413, ErrorCode::Validation, false),
        (422, ErrorCode::Validation, false),
        (418, ErrorCode::Validation, false),
        (408, ErrorCode::Timeout, true),
        (429, ErrorCode::RateLimited, true),
        (500, ErrorCode::Unavailable, true),
        (501, ErrorCode::Unsupported, false),
        (502, ErrorCode::Unavailable, true),
        (503, ErrorCode::Unavailable, true),
        (504, ErrorCode::Timeout, true),
        (599, ErrorCode::Unavailable, true),
    ];
    for (status, _, _) in cases {
        Mock::given(path(format!("/s{status}")))
            .respond_with(ResponseTemplate::new(status))
            .mount(&server)
            .await;
    }
    let t = transport(&server, |b| b.max_retries(0));
    for (status, code, retryable) in cases {
        let err = t
            .get(&format!("/s{status}"))
            .operation("op")
            .send()
            .await
            .unwrap_err();
        assert_eq!(err.code(), code, "status {status}");
        assert_eq!(err.http_status(), Some(status));
        assert_eq!(err.is_retryable(), retryable, "status {status}");
        assert!(
            err.message().ends_with(&format!("(HTTP {status})")),
            "{err}"
        );
    }
    // ok_status turns an error status into a response
    let resp = t.get("/s404").ok_status(404).send().await.unwrap();
    assert_eq!(resp.status(), 404);
}

#[tokio::test]
async fn core_errors_vendor_message() {
    let server = MockServer::start().await;
    Mock::given(path("/json"))
        .respond_with(
            ResponseTemplate::new(400)
                .set_body_json(json!({"errors": [{"message": "field x is required"}]})),
        )
        .mount(&server)
        .await;
    Mock::given(path("/text"))
        .respond_with(
            ResponseTemplate::new(404).set_body_string(format!("{}\nsecond line", "y".repeat(400))),
        )
        .mount(&server)
        .await;
    Mock::given(path("/html"))
        .respond_with(ResponseTemplate::new(502).set_body_string("<html>bad gateway</html>"))
        .mount(&server)
        .await;
    Mock::given(path("/plain"))
        .respond_with(ResponseTemplate::new(409).set_body_string("   "))
        .mount(&server)
        .await;
    Mock::given(path("/num"))
        .respond_with(ResponseTemplate::new(409).set_body_json(json!({"error": 42})))
        .mount(&server)
        .await;
    let t = transport(&server, |b| b.max_retries(0));
    let err = t
        .get("/json")
        .operation("kv.read secret/app")
        .send()
        .await
        .unwrap_err();
    assert_eq!(
        err.message(),
        "kv.read secret/app: invalid request: field x is required (HTTP 400)"
    );
    let err = t.get("/text").operation("op").send().await.unwrap_err();
    assert!(err.message().contains(&format!("{}…", "y".repeat(300))));
    assert!(!err.message().contains("second line"));
    let err = t.get("/html").operation("op").send().await.unwrap_err();
    assert_eq!(err.message(), "op: service unavailable (HTTP 502)");
    let err = t.get("/plain").operation("op").send().await.unwrap_err();
    assert_eq!(err.message(), "op: conflict (HTTP 409)");
    let err = t.get("/num").send().await.unwrap_err();
    assert_eq!(err.message(), "GET /num: conflict (HTTP 409)");
}

#[tokio::test]
async fn core_redaction_error_text() {
    let token = Secret::new("super-secret-token-123");
    let server = MockServer::start().await;
    Mock::given(path("/auth"))
        .respond_with(
            ResponseTemplate::new(401)
                .set_body_json(json!({"message": "token super-secret-token-123 is invalid"})),
        )
        .mount(&server)
        .await;
    let rec = Recorder::new();
    let t = transport(&server, |b| {
        b.hooks(rec.clone())
            .header("x-api-key", "header-secret-value")
    });
    t.add_known_secret(&Secret::new("abc"));
    let err = t
        .get("/auth")
        .query("token", "super-secret-token-123")
        .query("page", "2")
        .bearer(&token)
        .send()
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Authentication);
    assert!(err.message().contains("[REDACTED] is invalid"), "{err}");
    let all = format!("{err} {err:?} {}", rec.dump());
    assert!(!all.contains("super-secret-token-123"), "{all}");
    assert!(!all.contains("header-secret-value"), "{all}");
    let req = &rec.requests()[0];
    assert_eq!(req.headers["authorization"], "[REDACTED]");
    assert_eq!(req.headers["x-api-key"], "[REDACTED]");
    assert!(req.url.contains("page=2"));
    // a request header passed in clear is still redacted by name
    let err = t
        .get("/auth")
        .header("Authorization", "Bearer other-token-xyz")
        .send()
        .await
        .unwrap_err();
    assert!(!rec.dump().contains("other-token-xyz"));
    assert_eq!(err.code(), ErrorCode::Authentication);
    assert_eq!(t.redact("say super-secret-token-123"), "say [REDACTED]");
}

