#[tokio::test]
async fn core_hooks() {
    let server = MockServer::start().await;
    Mock::given(path("/h"))
        .respond_with(ResponseTemplate::new(503))
        .up_to_n_times(1)
        .mount(&server)
        .await;
    Mock::given(path("/h"))
        .respond_with(ResponseTemplate::new(200).insert_header("x-amzn-requestid", "amz-1"))
        .mount(&server)
        .await;
    let rec = Recorder::new();
    let t = transport(&server, |b| b.hooks(rec.clone()));
    t.get("/h")
        .query("secret", "s3cr3t-q")
        .send()
        .await
        .unwrap();
    let reqs = rec.requests();
    assert_eq!(reqs.len(), 2);
    assert_eq!(reqs[0].method, "GET");
    assert!(
        reqs[0].url.contains("secret=%5BREDACTED%5D"),
        "{}",
        reqs[0].url
    );
    assert!(reqs[0].headers.contains_key("user-agent"));
    let resps = rec.responses();
    assert_eq!(
        resps.iter().map(|r| r.status).collect::<Vec<_>>(),
        vec![503, 200]
    );
    assert_eq!(resps[1].attempt, 2);
    assert_eq!(resps[1].request_id.as_deref(), Some("amz-1"));
    let errs = rec.errors();
    assert_eq!(errs.len(), 1);
    assert!(errs[0].will_retry);
    assert_eq!(errs[0].attempt, 1);

    // panicking hooks are ignored
    let t = transport(&server, |b| b.hooks(Arc::new(Panicker)));
    let resp = t.get("/h").send().await.unwrap();
    assert_eq!(resp.status(), 200);
    Mock::given(path("/fail"))
        .respond_with(ResponseTemplate::new(400))
        .mount(&server)
        .await;
    assert_eq!(
        t.get("/fail").send().await.unwrap_err().code(),
        ErrorCode::Validation
    );
}

#[tokio::test]
async fn core_health_unreachable_transport() {
    // connection refused is retried (nothing was sent) and maps to UNAVAILABLE
    let port = closed_port();
    let cfg = sdk::core::CommonConfig::builder()
        .url(format!("http://127.0.0.1:{port}"))
        .retry(fast_retry(0.0))
        .build("http://unused")
        .unwrap();
    let rec = Recorder::new();
    let cfg2 = sdk::core::CommonConfig::builder()
        .url(format!("http://127.0.0.1:{port}"))
        .retry(fast_retry(0.0))
        .hooks(rec.clone())
        .build("http://unused")
        .unwrap();
    let t = HttpTransport::new(&cfg).unwrap();
    let err = t.post("/x").send().await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Unavailable);
    assert!(err.message().contains("connection failed"));
    assert!(std::error::Error::source(&err).is_some());
    let t = HttpTransport::new(&cfg2).unwrap();
    t.post("/x").send().await.unwrap_err();
    assert_eq!(rec.requests().len(), 4);
}

#[tokio::test]
async fn transport_request_building() {
    let server = MockServer::start().await;
    Mock::given(method("PUT"))
        .and(path("/base/v1/items"))
        .and(query_param("a", "1"))
        .and(query_param("b", "x y"))
        .and(header("x-extra", "e"))
        .and(header("x-config", "c"))
        .and(header("content-type", "application/json"))
        .respond_with(ResponseTemplate::new(200).set_body_string("plain"))
        .mount(&server)
        .await;
    Mock::given(method("DELETE"))
        .and(path("/base/abs"))
        .respond_with(ResponseTemplate::new(200).set_body_bytes(vec![0xff, 0xfe]))
        .mount(&server)
        .await;
    let cfg = sdk::core::CommonConfig::builder()
        .url(format!("{}/base/", server.uri()))
        .header("x-config", "c")
        .max_retries(0)
        .build("http://unused")
        .unwrap();
    let t = HttpTransport::new(&cfg).unwrap();
    assert!(format!("{t:?}").contains("HttpTransport"));
    assert_eq!(t.config().url().path(), "/base/");
    let resp = t
        .put("v1/items?a=1")
        .query("b", "x y")
        .header("x-extra", "e")
        .json(&json!({"k": "v"}))
        .send()
        .await
        .unwrap();
    assert_eq!(resp.text().unwrap(), "plain");
    assert!(resp.header("content-length").is_some());
    assert!(!resp.headers().is_empty());
    assert_eq!(resp.bytes().as_ref(), b"plain");
    assert!(resp.request_id().is_none());
    assert_eq!(
        resp.json::<serde_json::Value>().unwrap_err().code(),
        ErrorCode::Validation
    );
    let resp = t
        .request(Method::DELETE, &format!("{}/base/abs", server.uri()))
        .send()
        .await
        .unwrap();
    assert_eq!(resp.text().unwrap_err().code(), ErrorCode::Validation);

    // invalid inputs
    let err = t
        .get("/x")
        .header("bad header", "v")
        .send()
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Validation);
    let err = t
        .get("/x")
        .header("x-ok", "bad\nvalue")
        .send()
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Validation);
    let err = t.get("http://[bad").send().await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Validation);
    let mut bad = std::collections::HashMap::new();
    bad.insert(vec![1u8], 1);
    let err = t
        .post("/x")
        .operation("op")
        .json(&bad)
        .send()
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Validation);
    assert_eq!(err.message(), "op: invalid request body");
    let rb = t.get("/dbg");
    assert!(format!("{rb:?}").contains("/dbg"));
}

#[tokio::test]
async fn transport_tls_and_proxy_config() {
    let fixtures = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures");
    let server = MockServer::start().await;
    // valid CA (file + PEM) and client identity
    let pem = std::fs::read_to_string(format!("{fixtures}/ca.pem")).unwrap();
    let cfg = config(&server, |b| {
        b.ca_cert_path(format!("{fixtures}/ca.pem"))
            .ca_cert_pem(pem.clone())
            .client_cert(
                format!("{fixtures}/client.pem"),
                format!("{fixtures}/client.key"),
            )
            .insecure_skip_verify(true)
            .proxy("http://user:pw@127.0.0.1:3128")
    });
    assert!(HttpTransport::new(&cfg).is_ok());
    // a second insecure transport does not warn again (covered by Once)
    assert!(HttpTransport::new(&cfg).is_ok());

    let missing = config(&server, |b| b.ca_cert_path("/nonexistent/ca.pem"));
    let err = HttpTransport::new(&missing).unwrap_err();
    assert_eq!(err.code(), ErrorCode::Config);
    assert!(err.message().contains("cannot be read"));

    let empty = config(&server, |b| b.ca_cert_pem("no certificates here"));
    assert_eq!(
        HttpTransport::new(&empty).unwrap_err().code(),
        ErrorCode::Config
    );
    let garbage = config(&server, |b| {
        b.ca_cert_pem("-----BEGIN CERTIFICATE-----\n!!!!\n-----END CERTIFICATE-----\n")
    });
    assert_eq!(
        HttpTransport::new(&garbage).unwrap_err().code(),
        ErrorCode::Config
    );

    let bad_identity = config(&server, |b| {
        b.client_cert(format!("{fixtures}/ca.pem"), format!("{fixtures}/ca.pem"))
    });
    assert_eq!(
        HttpTransport::new(&bad_identity).unwrap_err().code(),
        ErrorCode::Config
    );
}

#[tokio::test]
async fn transport_no_retry_switch() {
    let server = MockServer::start().await;
    Mock::given(path("/once"))
        .respond_with(ResponseTemplate::new(503))
        .mount(&server)
        .await;
    let t = transport(&server, |b| b);
    let err = t.get("/once").no_retry().send().await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Unavailable);
    assert_eq!(hits(&server).await, 1, "no retry for this request");
    let err = t.get("/once").send().await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Unavailable);
    assert_eq!(
        hits(&server).await,
        5,
        "the config still retries other requests"
    );
}

#[tokio::test]
async fn transport_retry_after_hook() {
    let server = MockServer::start().await;
    Mock::given(path("/limited"))
        .respond_with(
            ResponseTemplate::new(429)
                .insert_header("x-ratelimit-reset", "0.05")
                .insert_header("retry-after", "3600"),
        )
        .up_to_n_times(1)
        .mount(&server)
        .await;
    Mock::given(path("/limited"))
        .respond_with(ResponseTemplate::new(200))
        .mount(&server)
        .await;
    Mock::given(path("/plain"))
        .respond_with(ResponseTemplate::new(429).insert_header("retry-after", "0"))
        .up_to_n_times(1)
        .mount(&server)
        .await;
    Mock::given(path("/plain"))
        .respond_with(ResponseTemplate::new(200))
        .mount(&server)
        .await;
    let t = HttpTransport::new(&config(&server, |b| b))
        .unwrap()
        .with_retry_after_hook(|_status, headers| {
            headers
                .get("x-ratelimit-reset")
                .and_then(|v| v.to_str().ok())
                .and_then(|v| v.parse::<f64>().ok())
                .map(Duration::from_secs_f64)
        });
    // the hook's 50 ms wins over Retry-After: 3600 (which is beyond max_retry_after)
    let started = Instant::now();
    assert_eq!(t.get("/limited").send().await.unwrap().status(), 200);
    assert!(started.elapsed() < Duration::from_secs(5));
    // no vendor header: Retry-After applies as before
    assert_eq!(t.get("/plain").send().await.unwrap().status(), 200);

    // a panicking hook is ignored
    let boom = MockServer::start().await;
    Mock::given(path("/b"))
        .respond_with(ResponseTemplate::new(404).insert_header("x-boom", "1"))
        .mount(&boom)
        .await;
    let t = HttpTransport::new(&config(&boom, |b| b))
        .unwrap()
        .with_retry_after_hook(|_, h| {
            if h.contains_key("x-boom") {
                panic!("hook failure (expected in tests)");
            }
            None
        });
    assert_eq!(
        t.get("/b").send().await.unwrap_err().code(),
        ErrorCode::NotFound
    );
}

#[tokio::test]
async fn transport_shared_client_and_urls() {
    let server = MockServer::start().await;
    Mock::given(path("/base/stream"))
        .and(header("user-agent", default_user_agent().as_str()))
        .respond_with(ResponseTemplate::new(200).set_body_string("data: 1\n\n"))
        .mount(&server)
        .await;
    let t = transport(&server, |b| b.url(format!("{}/base/", server.uri())));
    let url = t.url_for("stream?x=1").unwrap();
    assert_eq!(url.as_str(), format!("{}/base/stream?x=1", server.uri()));
    assert_eq!(
        t.url_for("https://other.example/a").unwrap().as_str(),
        "https://other.example/a"
    );
    assert_eq!(
        t.url_for("http://[bad").unwrap_err().code(),
        ErrorCode::Validation
    );
    // the raw reqwest client serves streaming calls the buffered API cannot
    let resp = t
        .reqwest_client()
        .get(t.url_for("/stream").unwrap())
        .header("user-agent", t.user_agent())
        .send()
        .await
        .unwrap();
    assert_eq!(resp.text().await.unwrap(), "data: 1\n\n");

    assert!(t.ensure_open("op").is_ok());
    t.close();
    let err = t.ensure_open("logs.tail").unwrap_err();
    assert_eq!(err.code(), ErrorCode::Cancelled);
    assert!(err.message().contains("logs.tail: client is closed"));
}

#[test]
fn transport_reqwest_client_builders() {
    use sdk::core::{build_reqwest_client, reqwest_client_builder, user_agent_for, CommonConfig};
    let fixtures = concat!(env!("CARGO_MANIFEST_DIR"), "/tests/fixtures");
    let cfg = CommonConfig::builder()
        .ca_cert_path(format!("{fixtures}/ca.pem"))
        .proxy("http://127.0.0.1:3128")
        .user_agent_suffix("app/2")
        .build("http://127.0.0.1:1")
        .unwrap();
    assert!(build_reqwest_client(&cfg).is_ok());
    assert!(reqwest_client_builder(&cfg).unwrap().build().is_ok());
    assert_eq!(
        user_agent_for(&cfg),
        format!("{} app/2", default_user_agent())
    );
    let plain = CommonConfig::builder().build("http://127.0.0.1:1").unwrap();
    assert_eq!(user_agent_for(&plain), default_user_agent());
    let bad = CommonConfig::builder()
        .ca_cert_path("/nonexistent/ca.pem")
        .build("http://127.0.0.1:1")
        .unwrap();
    assert_eq!(
        build_reqwest_client(&bad).unwrap_err().code(),
        ErrorCode::Config
    );
}

#[test]
fn closed_port_is_refused_and_not_ephemeral() {
    // a reserved port cannot be taken over by a mock server a parallel test binds to port 0
    let port = closed_port();
    assert!(port == RESERVED_CLOSED_PORT || port >= 1024, "{port}");
    let addr = std::net::SocketAddr::from(([127, 0, 0, 1], port));
    let err = std::net::TcpStream::connect_timeout(&addr, Duration::from_secs(1)).unwrap_err();
    assert_eq!(err.kind(), std::io::ErrorKind::ConnectionRefused);
}

