#[tokio::test]
async fn transport_error_mapper_runs_before_hooks_and_retries() {
    let server = MockServer::start().await;
    Mock::given(path("/conflict"))
        .respond_with(
            ResponseTemplate::new(400)
                .insert_header("x-request-id", "req-7")
                .set_body_json(json!({"code": "already_exists", "message": "dup"})),
        )
        .mount(&server)
        .await;
    Mock::given(path("/busy"))
        .respond_with(ResponseTemplate::new(503).set_body_json(json!({"code": "maintenance"})))
        .mount(&server)
        .await;
    Mock::given(path("/plain"))
        .respond_with(ResponseTemplate::new(404))
        .mount(&server)
        .await;
    let rec = Recorder::new();
    let t = HttpTransport::new(&config(&server, |b| b.hooks(rec.clone())))
        .unwrap()
        .with_error_mapper(|r: &ErrorResponse<'_>| {
            let code = r.json::<serde_json::Value>()?["code"].as_str()?.to_owned();
            assert_eq!(r.text().map(|t| t.contains(&code)), Some(true));
            match code.as_str() {
                "already_exists" => {
                    assert_eq!(r.status, 400);
                    assert_eq!(r.method, &Method::GET);
                    assert_eq!(r.attempt, 1);
                    assert_eq!(r.request_id, Some("req-7"));
                    assert_eq!(r.headers["x-request-id"], "req-7");
                    assert_eq!(r.vendor_text().as_deref(), Some("dup"));
                    assert_eq!(r.default_error.code(), ErrorCode::Validation);
                    assert!(r.operation.contains("/conflict"));
                    Some(Error::conflict(format!(
                        "{}: exists (secret-value-123)",
                        r.operation
                    )))
                }
                // not retryable: a 503 the vendor reports as maintenance is returned at once
                _ => Some(Error::unsupported("maintenance").with_retryable(false)),
            }
        });
    t.add_known_secret(&Secret::new("secret-value-123"));
    let err = t.get("/conflict").send().await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Conflict);
    assert_eq!(err.http_status(), Some(400));
    assert_eq!(err.request_id(), Some("req-7"));
    assert!(err.message().contains("exists ([REDACTED])"), "{err}");
    // hooks see the mapped error
    assert_eq!(rec.errors()[0].error.code(), ErrorCode::Conflict);
    assert!(!rec.dump().contains("secret-value-123"));

    let err = t.get("/busy").send().await.unwrap_err();
    assert_eq!(err.code(), ErrorCode::Unsupported);
    let seen = server.received_requests().await.unwrap();
    assert_eq!(seen.iter().filter(|r| r.url.path() == "/busy").count(), 1);

    // the mapper returned None: canonical error
    assert_eq!(
        t.get("/plain").send().await.unwrap_err().code(),
        ErrorCode::NotFound
    );
}

#[tokio::test]
async fn transport_request_error_mapper_wins_and_falls_back() {
    let server = MockServer::start().await;
    Mock::given(path("/busy"))
        .respond_with(ResponseTemplate::new(503))
        .mount(&server)
        .await;
    Mock::given(path("/bad"))
        .respond_with(ResponseTemplate::new(400))
        .mount(&server)
        .await;
    let t = HttpTransport::new(&config(&server, |b| b))
        .unwrap()
        .with_error_mapper(|r| (r.status == 400).then(|| Error::not_found("from transport")));
    // per-request mapper first; a mapped retryable error on a retryable status is retried
    let calls = std::sync::atomic::AtomicU32::new(0);
    let err = t
        .get("/busy")
        .map_error(|r| {
            calls.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
            Some(Error::unavailable(format!("{}: vendor busy", r.operation)).with_status(599))
        })
        .send()
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Unavailable);
    // a status set by the mapper is kept; 1 attempt + 3 retries
    assert_eq!(err.http_status(), Some(599));
    assert_eq!(calls.load(std::sync::atomic::Ordering::SeqCst), 4);
    // per-request None → transport mapper
    let err = t.get("/bad").map_error(|_| None).send().await.unwrap_err();
    assert_eq!(err.message(), "from transport");
    // a retryable mapped error on a non-retryable status is not retried
    let err = t
        .get("/bad")
        .map_error(|_| Some(Error::unavailable("retry me?")))
        .send()
        .await
        .unwrap_err();
    assert_eq!(err.message(), "retry me?");
    let bad = server.received_requests().await.unwrap();
    assert_eq!(bad.iter().filter(|r| r.url.path() == "/bad").count(), 2);
    // a panicking mapper counts as None
    let err = t
        .get("/busy")
        .no_retry()
        .map_error(|_| panic!("mapper failure (expected in tests)"))
        .send()
        .await
        .unwrap_err();
    assert_eq!(err.code(), ErrorCode::Unavailable);
    assert!(err.message().contains("(HTTP 503)"), "{err}");
}
